[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "tokyo-itinerary-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "tokyo-itinerary-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "title_text",
                "type": "Text",
                "properties": {
                  "text": "5-Day Tokyo Itinerary: Shinjuku & Shibuya",
                  "style": "headline5"
                }
              },
              {
                "id": "assumptions_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "assumptions_column",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "assumptions_title",
                          "type": "Text",
                          "properties": {
                            "text": "Assumptions",
                            "style": "headline6"
                          }
                        },
                        {
                          "id": "assumption_1",
                          "type": "Text",
                          "properties": {
                            "text": "• Trip dates 2025-05-15 to 2025-05-20 imply 5 full activity days, with May 20th as a departure day."
                          }
                        },
                        {
                          "id": "assumption_2",
                          "type": "Text",
                          "properties": {
                            "text": "• Budget of $50 per person per meal is for a main course and a drink/side."
                          }
                        },
                        {
                          "id": "assumption_3",
                          "type": "Text",
                          "properties": {
                            "text": "• Travel within Tokyo will primarily be via public transport."
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "itinerary_tabs",
                "type": "Tabs",
                "properties": {
                  "children": [
                    {
                      "id": "tab_day1",
                      "type": "Tab",
                      "properties": {
                        "label": "Day 1",
                        "child": {
                          "id": "day1_content",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "day1_title",
                                "type": "Text",
                                "properties": {
                                  "text": "Thursday, May 15: Shinjuku Arrival & Gardens",
                                  "style": "subtitle1"
                                }
                              },
                              {
                                "id": "day1_morning",
                                "type": "Text",
                                "properties": {
                                  "text": "Morning: Arrive in Tokyo, check into your accommodation in Shinjuku or Shibuya."
                                }
                              },
                              {
                                "id": "day1_afternoon",
                                "type": "Text",
                                "properties": {
                                  "text": "Afternoon: Stroll through Shinjuku Gyoen National Garden."
                                }
                              },
                              {
                                "id": "day1_late_afternoon",
                                "type": "Text",
                                "properties": {
                                  "text": "Late Afternoon: Visit the Tokyo Metropolitan Government Building for panoramic views."
                                }
                              },
                              {
                                "id": "day1_evening",
                                "type": "Text",
                                "properties": {
                                  "text": "Evening: Dinner in Shinjuku. Explore Shinjuku Golden Gai or Omoide Yokocho for atmosphere."
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "tab_day2",
                      "type": "Tab",
                      "properties": {
                        "label": "Day 2",
                        "child": {
                          "id": "day2_content",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "day2_title",
                                "type": "Text",
                                "properties": {
                                  "text": "Friday, May 16: Shibuya Icons & Views",
                                  "style": "subtitle1"
                                }
                              },
                              {
                                "id": "day2_morning",
                                "type": "Text",
                                "properties": {
                                  "text": "Morning: Experience Shibuya Crossing & see the Hachiko Statue."
                                }
                              },
                              {
                                "id": "day2_afternoon",
                                "type": "Text",
                                "properties": {
                                  "text": "Afternoon: Ascend Shibuya Sky for 360-degree views and explore Shibuya Center Gai."
                                }
                              },
                              {
                                "id": "day2_evening",
                                "type": "Text",
                                "properties": {
                                  "text": "Evening: Dinner in Shibuya and shopping around Shibuya 109."
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "tab_day3",
                      "type": "Tab",
                      "properties": {
                        "label": "Day 3",
                        "child": {
                          "id": "day3_content",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "day3_title",
                                "type": "Text",
                                "properties": {
                                  "text": "Saturday, May 17: Shinjuku Shopping & Culture",
                                  "style": "subtitle1"
                                }
                              },
                              {
                                "id": "day3_morning",
                                "type": "Text",
                                "properties": {
                                  "text": "Morning: Explore department stores like Isetan, Takashimaya, and Lumine EST."
                                }
                              },
                              {
                                "id": "day3_afternoon",
                                "type": "Text",
                                "properties": {
                                  "text": "Afternoon: Visit the Samurai Museum (optional) or explore quieter side streets."
                                }
                              },
                              {
                                "id": "day3_evening",
                                "type": "Text",
                                "properties": {
                                  "text": "Evening: Dinner in Shinjuku and experience the atmosphere of Kabukicho."
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "tab_day4",
                      "type": "Tab",
                      "properties": {
                        "label": "Day 4",
                        "child": {
                          "id": "day4_content",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "day4_title",
                                "type": "Text",
                                "properties": {
                                  "text": "Sunday, May 18: Harajuku Fashion & Meiji Jingu",
                                  "style": "subtitle1"
                                }
                              },
                              {
                                "id": "day4_morning",
                                "type": "Text",
                                "properties": {
                                  "text": "Morning: Visit the serene Meiji Jingu Shrine."
                                }
                              },
                              {
                                "id": "day4_afternoon",
                                "type": "Text",
                                "properties": {
                                  "text": "Afternoon: Explore Takeshita Street, Omotesando, and Cat Street in Harajuku."
                                }
                              },
                              {
                                "id": "day4_evening",
                                "type": "Text",
                                "properties": {
                                  "text": "Evening: Dinner in Harajuku or return to Shibuya/Shinjuku. Consider a themed cafe."
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "tab_day5",
                      "type": "Tab",
                      "properties": {
                        "label": "Day 5",
                        "child": {
                          "id": "day5_content",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "day5_title",
                                "type": "Text",
                                "properties": {
                                  "text": "Monday, May 19: Modern Art & Departure Prep",
                                  "style": "subtitle1"
                                }
                              },
                              {
                                "id": "day5_morning",
                                "type": "Text",
                                "properties": {
                                  "text": "Morning: Experience immersive digital art at TeamLab Planets TOKYO (Toyosu)."
                                }
                              },
                              {
                                "id": "day5_afternoon",
                                "type": "Text",
                                "properties": {
                                  "text": "Afternoon: Last-minute souvenir shopping and packing in Shinjuku or Shibuya."
                                }
                              },
                              {
                                "id": "day5_evening",
                                "type": "Text",
                                "properties": {
                                  "text": "Evening: Enjoy a final farewell dinner."
                                }
                              }
                            ]
                          }
                        }
                      }
                    }
                  ]
                }
              },
              {
                "id": "divider_1",
                "type": "Divider"
              },
              {
                "id": "restaurants_title",
                "type": "Text",
                "properties": {
                  "text": "Restaurant Recommendations (~$50/person)",
                  "style": "headline6"
                }
              },
              {
                "id": "restaurants_disclaimer",
                "type": "Text",
                "properties": {
                  "text": "These are examples. Please check restaurant websites for current menus, prices, and reservations.",
                  "style": "caption"
                }
              },
              {
                "id": "restaurants_list",
                "type": "List",
                "properties": {
                  "children": [
                    {
                      "id": "restaurant_1_item",
                      "type": "ListItem",
                      "properties": {
                        "child": {
                          "id": "restaurant_1_col",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "restaurant_1_name",
                                "type": "Text",
                                "properties": {
                                  "text": "Afuri Ramen",
                                  "style": "subtitle2"
                                }
                              },
                              {
                                "id": "restaurant_1_summary",
                                "type": "Text",
                                "properties": {
                                  "text": "Famous for its refreshing yuzu-scented broth, Afuri offers a lighter, yet flavorful ramen experience."
                                }
                              },
                              {
                                "id": "restaurant_1_attr",
                                "type": "Text",
                                "properties": {
                                  "text": "Key attribute: Yuzu Shio Ramen, typically under $15 per person.",
                                  "style": "caption"
                                }
                              },
                              {
                                "id": "restaurant_1_button",
                                "type": "Button",
                                "properties": {
                                  "label": "Visit Website",
                                  "variant": "text",
                                  "action": {
                                    "type": "functionCall",
                                    "call": "openUrl",
                                    "arguments": {
                                      "url": "https://afuri.com/"
                                    }
                                  }
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "restaurant_2_item",
                      "type": "ListItem",
                      "properties": {
                        "child": {
                          "id": "restaurant_2_col",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "restaurant_2_name",
                                "type": "Text",
                                "properties": {
                                  "text": "Katsukura Shinjuku Takashimaya",
                                  "style": "subtitle2"
                                }
                              },
                              {
                                "id": "restaurant_2_summary",
                                "type": "Text",
                                "properties": {
                                  "text": "A highly-regarded tonkatsu (fried pork cutlet) restaurant offering premium pork."
                                }
                              },
                              {
                                "id": "restaurant_2_attr",
                                "type": "Text",
                                "properties": {
                                  "text": "Key attribute: High-quality Tonkatsu sets, around $20-$30 per person.",
                                  "style": "caption"
                                }
                              },
                              {
                                "id": "restaurant_2_button",
                                "type": "Button",
                                "properties": {
                                  "label": "Visit Website",
                                  "variant": "text",
                                  "action": {
                                    "type": "functionCall",
                                    "call": "openUrl",
                                    "arguments": {
                                      "url": "https://www.katsukura.jp/"
                                    }
                                  }
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "restaurant_3_item",
                      "type": "ListItem",
                      "properties": {
                        "child": {
                          "id": "restaurant_3_col",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "restaurant_3_name",
                                "type": "Text",
                                "properties": {
                                  "text": "Uobei Sushi (Shibuya)",
                                  "style": "subtitle2"
                                }
                              },
                              {
                                "id": "restaurant_3_summary",
                                "type": "Text",
                                "properties": {
                                  "text": "A lively and modern conveyor-belt sushi restaurant with high-speed delivery lanes."
                                }
                              },
                              {
                                "id": "restaurant_3_attr",
                                "type": "Text",
                                "properties": {
                                  "text": "Key attribute: Fresh, affordable sushi delivered fast, typically under $20 per person.",
                                  "style": "caption"
                                }
                              },
                              {
                                "id": "restaurant_3_button",
                                "type": "Button",
                                "properties": {
                                  "label": "Visit Website",
                                  "variant": "text",
                                  "action": {
                                    "type": "functionCall",
                                    "call": "openUrl",
                                    "arguments": {
                                      "url": "https://www.genkisushi.co.jp/uobei/"
                                    }
                                  }
                                }
                              }
                            ]
                          }
                        }
                      }
                    }
                  ]
                }
              },
              {
                "id": "divider_2",
                "type": "Divider"
              },
              {
                "id": "actions_title",
                "type": "Text",
                "properties": {
                  "text": "Quick Actions",
                  "style": "headline6"
                }
              },
              {
                "id": "actions_row",
                "type": "Row",
                "properties": {
                  "children": [
                    {
                      "id": "button_flights",
                      "type": "Button",
                      "properties": {
                        "label": "Book Flights",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.google.com/flights"
                          }
                        }
                      }
                    },
                    {
                      "id": "button_hotels",
                      "type": "Button",
                      "properties": {
                        "label": "Find Hotels",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.booking.com/city/jp/tokyo.html"
                          }
                        }
                      }
                    },
                    {
                      "id": "button_metro",
                      "type": "Button",
                      "properties": {
                        "label": "Metro Pass",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.tokyometro.jp/en/ticket/travel/"
                          }
                        }
                      }
                    },
                    {
                      "id": "button_teamlab",
                      "type": "Button",
                      "properties": {
                        "label": "TeamLab Tickets",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://planets.teamlab.art/tokyo/"
                          }
                        }
                      }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    }
  }
]
